/** Conservative certificates: ALL tracked bytes and actual installed tools are inputs.
 * No dependency inference or cached generated bytes. A miss always regenerates. */
const crypto = require('node:crypto');
const fs = require('node:fs');
const path = require('node:path');
const { spawnSync } = require('node:child_process');

function hashFiles(root, files) {
  const hash = crypto.createHash('sha256');
  for (const file of [...files].sort((a, b) => a.localeCompare(b))) {
    const full = path.join(root, file),
      stat = fs.lstatSync(full);
    if (!stat.isFile()) throw new Error(`Not a regular tracked file: ${file}`);
    hash.update(JSON.stringify([file, stat.mode & 0o777, stat.size]));
    hash.update(fs.readFileSync(full));
  }
  return hash.digest('hex');
}
function trackedFiles(root) {
  const env = { ...process.env };
  for (const key of Object.keys(env)) if (key.startsWith('GIT_')) delete env[key];
  const got = spawnSync('git', ['ls-files', '-z'], { cwd: root, env, encoding: 'utf8' });
  if (got.status !== 0 || got.error) throw new Error(`Cannot list tracked inputs: ${got.stderr}`);
  const files = got.stdout.split('\0').filter(Boolean);
  if (!files.length) throw new Error('No tracked source files');
  return files;
}
function toolFingerprint(root) {
  const hash = crypto.createHash('sha256'),
    seen = new Set();
  function walk(full) {
    const real = fs.realpathSync(full);
    hash.update(JSON.stringify([full, real]));
    if (seen.has(real)) return;
    seen.add(real);
    const stat = fs.statSync(real);
    hash.update(String(stat.mode & 0o777));
    if (stat.isDirectory()) {
      for (const name of fs.readdirSync(real).sort((a, b) => a.localeCompare(b))) {
        walk(path.join(real, name));
      }
    } else if (stat.isFile()) {
      const fd = fs.openSync(real, 'r'),
        chunk = Buffer.alloc(1024 * 1024);
      try {
        let n;
        while ((n = fs.readSync(fd, chunk)) > 0) hash.update(chunk.subarray(0, n));
      } finally {
        fs.closeSync(fd);
      }
    } else throw new Error(`Unsupported tool input: ${full}`);
  }
  const python = spawnSync(
    process.env.PYTHON || 'python3',
    [
      '-B',
      '-c',
      'import json,sys,sysconfig,pathlib; p=[sys.executable]+[str(pathlib.Path(q).resolve()) for q in sys.path if q and pathlib.Path(q).exists()]; lib=pathlib.Path(sysconfig.get_config_var("LIBDIR"))/str(sysconfig.get_config_var("LDLIBRARY")); print(json.dumps(p+([str(lib)] if lib.exists() else [])))',
    ],
    { encoding: 'utf8', timeout: 30_000 },
  );
  if (python.status !== 0 || python.error)
    throw new Error(`Cannot fingerprint Python: ${python.stderr}`);
  for (const name of ['npm', 'npx', 'git']) {
    const executable = (process.env.PATH || '')
      .split(path.delimiter)
      .map((dir) => path.join(dir, name))
      .find((file) => {
        try {
          fs.accessSync(file, fs.constants.X_OK);
          return true;
        } catch {
          return false;
        }
      });
    if (!executable) throw new Error(`Cannot fingerprint installed ${name}`);
    walk(executable);
    if (name === 'npm' || name === 'npx') walk(path.resolve(fs.realpathSync(executable), '../..'));
  }
  walk(process.execPath);
  walk(path.join(root, 'node_modules'));
  for (const full of JSON.parse(python.stdout)) walk(full);
  hash.update(JSON.stringify([process.version, process.platform, process.arch]));
  return hash.digest('hex');
}
function fingerprint({ root, tools = toolFingerprint(root) }) {
  const files = trackedFiles(root),
    source = hashFiles(root, files);
  // Include environment inputs such as density, Python search path, locale and TZ.
  // Only variables replaced by the owned snapshot or incidental shell state are omitted.
  const ignored =
    /^(GIT_|GARDEN_PREVIEW$|BATTLE_PREVIEW$|WORLD_PREVIEW$|MAP_PREVIEW$|ZONE_PREVIEW$|JOURNEY_PREVIEW$|PWD$|OLDPWD$|SHLVL$|_$|ART_REPRO_JOBS$)/;
  const env = Object.entries(process.env)
    .filter(([key]) => !ignored.test(key))
    .sort(([a], [b]) => a.localeCompare(b));
  const key = crypto
    .createHash('sha256')
    .update(JSON.stringify({ schema: 1, source, tools, env }))
    .digest('hex');
  return { key, source, files };
}
module.exports = { hashFiles, trackedFiles, toolFingerprint, fingerprint };
